try{await openDB(demoMode?'delivery-manager-demo':'delivery-manager');state=await read();if(demoMode&&!state.demoSeedVersion){state=createDemoData();await save(state);}if(demoMode&&ensureDemoCurrentShift(state)){await save(state);}if(demoMode&&ensureDemoAnalytics(state))await save(state);if(applySettingsDefaults(state))await save(state);completeRuns(state);await save(state);render();if(!demoMode){const reconcile=()=>syncNotifications(state).catch(()=>{});reconcile();addEventListener('online',reconcile);navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='open-run'){renderReturnGate();return;}if(e.data?.type==='open-eos'){if($('#modal').open)return notify('Close this form when ready to review your shift.');tab='shift';render();checkShiftReminder();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)reconcile();});setInterval(reconcile,60000);}setInterval(checkShiftReminder,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkShiftReminder();});setTimeout(()=>{if(!$('#modal').open)checkAlcoholReceiptJar();checkShiftReminder();},1000);registerUpdates().catch(()=>{});}catch(e){$('#app').innerHTML='<main class="main"><h1>We couldn’t open your records.</h1><p>Local storage may be unavailable. Please reopen this app in a regular browser window. No records have been reset.</p></main>';}
window.addEventListener('online',()=>state&&render());window.addEventListener('offline',()=>state&&render());

function hasDog(address){return !!state.addressNotes?.[addressKey(address)]?.barkingDog;}
function dogWarning(address){return hasDog(address)?'<div class="dog-warning">Barking dog — be prepared before approaching the door.</div>':'';}
function completionNotes(deliveryId){const d=state.deliveries.find(x=>x.id===deliveryId);dialog('Delivery completed',`<p>Delivery time recorded.</p><label class="checkbox-label"><input type="checkbox" id="barking-dog" ${hasDog(d.address)?'checked':''}> Barking dog at this address</label><p class="muted">Remembered on this device for future deliveries to this address.</p><label class="checkbox-label"><input type="checkbox" id="completion-no-text" ${doNotText(state,d.address)?'checked':''}> Do not text this address / unit</label>${d.isCatering?'<button type="button" class="primary" id="share-catering-complete">Share catering photos with Mike</button>':''}<div id="completion-text-wrap">${d.phone&&!doNotText(state,d.address)?'<button type="button" class="primary" id="completion-text">Prepare customer text</button>':`<p>${doNotText(state,d.address)?'Customer text skipped for this address.':'No customer phone number was entered.'}</p>`}</div>`,null,'Save','Done');let pending=Promise.resolve();const check=$('#barking-dog');check.onchange=()=>{const checked=check.checked;pending=pending.then(()=>mutate(v=>{v.addressNotes??={};setAddressPreference(v,d.address,'barkingDog',checked);})).catch(e=>notify(e.message));};const bindText=()=>{if($('#completion-text'))$('#completion-text').onclick=async()=>{await pending;customerMessage(d.id,'Delivery completed');};};bindText();$('#completion-no-text').onchange=async e=>{const checked=e.target.checked;await mutate(v=>setAddressPreference(v,d.address,'doNotText',checked));$('#completion-text-wrap').innerHTML=d.phone&&!checked?'<button type="button" class="primary" id="completion-text">Prepare customer text</button>':'<p>Customer text skipped for this address.</p>';bindText();};if($('#share-catering-complete'))$('#share-catering-complete').onclick=()=>shareCatering(d.id);}
function showRoute(stops){dialog('Your route is ready',`<ol class="route-addresses">${stops.map((d,i)=>`<li><strong>Delivery ${i+1}</strong><div>${esc(navigationAddress(d.address))}</div>${dogWarning(d.address)}<a href="${esc(firstStopURL(d.address))}">Navigate to this stop only</a></li>`).join('')}</ol><a class="primary" href="${esc(mapsURL(stops.map(d=>d.address)))}">Open ${stops.length>1?'batch route':'directions'} in Apple Maps</a><p class="muted">The route ends at the final delivery. Check locations in Maps before driving.</p>`,null,'Save','Done');}
function tasksView(){const shift=active(),tasks=shift?.tasks||{};return header('Your kitchen tasks.','Check only the work you completed this shift.')+(!shift?'<div class="card">Start a shift to record tasks.</div>':`<form id="tasks-form" class="card">${TASK_GROUPS.map(g=>`<div class="task-group"><label class="checkbox-label"><input type="checkbox" data-task-parent="${g.id}" name="${g.id}" ${tasks[g.id]?'checked':''}> ${g.label}</label>${g.children?`<div data-task-children="${g.id}" class="task-children" ${tasks[g.id]?'':'hidden'}>${g.children.map(c=>`<label class="checkbox-label"><input type="checkbox" name="${g.id}:${c}" ${tasks[`${g.id}:${c}`]?'checked':''}> ${c}</label>`).join('')}</div>`:''}</div>`).join('')}<label for="special-task">Other / special tasks completed</label><textarea id="special-task" name="special" maxlength="1000">${esc(tasks.special||'')}</textarea><button class="primary" type="submit">Save tasks</button><p class="muted">Changes save automatically. Only completed tasks are included in Mike’s report.</p></form>`);}
function bindTasks(){const form=$('#tasks-form');if(!form)return;form.querySelectorAll('[data-task-parent]').forEach(c=>c.onchange=()=>{const children=form.querySelector(`[data-task-children="${c.dataset.taskParent}"]`);if(children){children.hidden=!c.checked;if(!c.checked)children.querySelectorAll('input').forEach(i=>i.checked=false);}});form.onchange=form.onsubmit=async e=>{e.preventDefault();const shiftId=active().id,f=new FormData(form),tasks={special:String(f.get('special')||'').trim()};for(const g of TASK_GROUPS){tasks[g.id]=f.has(g.id);for(const c of g.children||[])tasks[`${g.id}:${c}`]=f.has(g.id)&&f.has(`${g.id}:${c}`);}try{await mutate(v=>{recordTasks(v.shifts.find(s=>s.id===shiftId),tasks,now());});notify('Tasks saved for this shift.');}catch(e){notify(e.message);}};}
const renderBase=render;render=function(){renderBase();bindTasks();};
function checkShiftReminder(){const s=active();if(!s||awaitingReturn(state)||document.hidden||$('#modal').open||busy||!reminderDue(s))return;dialog('Still on shift?',`<p>Delivery cutoff was over 30 minutes ago. If you’ve finished, record your ending mileage and prepare Mike’s report.</p><p>If you’re still working, we’ll remind you in 15 minutes.</p><button type="button" id="reminder-end" class="primary">End shift</button>`,null,'Save','Remind me in 15 minutes');const snooze=()=>mutate(v=>{const x=v.shifts.find(x=>x.id===s.id);if(x)x.reminderAfter=new Date(Date.now()+15*60000).toISOString();}).catch(e=>notify(e.message));$('#modal').querySelector('[data-close]').onclick=async()=>{await snooze();$('#modal').close();};$('#modal').oncancel=()=>{snooze();};$('#reminder-end').onclick=async()=>{await snooze();$('#modal').close();handle('end').catch(e=>notify(e.message));};}
function setupScanner(){const form=$('#modal form');$('#scan-ticket').onclick=()=>openTicketScanner(result=>{if(!form.isConnected)return;for(const [key,selector] of Object.entries({name:'#customer',phone:'#phone',address:'#address',ticket:'#ticket'}))form.querySelector(selector).value=result[key]||'';form.querySelector('#do-not-text').checked=doNotText(state,form.querySelector('#address').value);form.querySelector('#scan-status').textContent='Ticket scanned. Check the name, phone, street number and unit below. Unreadable fields are left blank. Confirm drinks, alcohol and scheduled time before adding.';});}

function notificationSettings(){const n=notificationStatus();return `<section class="card"><h2>Lock-screen reminders</h2><p class="muted">Free reminders at 9:00 p.m. Sunday–Thursday and 9:30 p.m. Friday–Saturday, if your shift is still open. Run reminders arrive 10, 25 and 45 minutes after the last drop-off until you tap End Run. Ending a run or shift cancels its reminder when online. Customer details stay on this device.</p>${demoMode?'<p>Notifications are disabled in sample mode.</p>':`${n.unsupported?`<p>${esc(n.unsupported)}</p>`:''}<p><strong>${n.enabled?'Enabled for this phone':'Not enabled'}</strong>${n.permission==='denied'?' · blocked in phone notification settings':''}</p>${n.pending?'<p class="dog-warning">Reminder update pending. Connect to the internet to finish scheduling or cancellation.</p>':''}${n.error?`<p class="error">${esc(n.error)}</p>`:''}${n.lastTest?`<p class="${n.lastTest.state==='failed'?'error':'hint'}" role="status" aria-live="polite">${esc(n.lastTest.message)}</p>`:''}<div class="actions">${n.enabled?`<button data-action="test-push" class="primary" ${n.lastTest?.state==='sending'?'disabled':''}>${n.lastTest?.state==='sending'?'Sending…':'Send test notification'}</button><button data-action="disable-push">Disable reminders</button>`:`<button data-action="enable-push" class="primary" ${n.unsupported?'disabled':''}>Enable lock-screen reminders</button>`}${n.pending?'<button data-action="retry-push">Retry connection</button>':''}</div><p class="muted">Focus settings and internet availability can delay alerts. Notification setup stays with this installation and isn’t included in backups.</p>`}</section>`;}

function bindReportCharts(){if($('#timeline-shift'))$('#timeline-shift').onchange=e=>{timelineShift=e.target.value;timelinePage=0;render();document.getElementById('report-timeline')?.scrollIntoView({block:'start'});};document.querySelectorAll('[data-timeline-page]').forEach(b=>b.onclick=()=>{timelinePage=Math.max(0,timelinePage+Number(b.dataset.timelinePage));render();document.getElementById('report-timeline')?.scrollIntoView({block:'start'});});document.querySelectorAll('[data-chart-note]').forEach(e=>{const show=()=>{const output=e.closest('.chart-card')?.querySelector('.chart-readout')||$('#chart-selection');if(output){output.textContent=e.dataset.chartNote;output.classList.add('has-value');}};e.onclick=show;e.onfocus=show;e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();show();}};});}

function renderReturnGate(){
 const run=awaitingReturn(state),shell=$('.app-shell');let gate=$('#return-gate');
 shell.inert=!!run;document.body.classList.toggle('return-pending',!!run);
 if(!run){gate?.remove();return;}
 if(!gate){gate=document.createElement('section');gate.id='return-gate';gate.className='return-gate';gate.setAttribute('role','dialog');gate.setAttribute('aria-modal','true');gate.setAttribute('aria-labelledby','return-title');gate.innerHTML=`<div class="return-panel"><span class="return-emblem">${icon('deliveries')}</span><p class="return-eyebrow">THE LAST STOP IS DONE</p><h2 id="return-title">One last thing.</h2><p>Back at the restaurant?<br>End your run to record your return.</p><button class="primary" id="end-run">End Run <span aria-hidden="true">✓</span></button><small>Tap only once you’re back. Your shift stays open.</small><p class="return-error" role="alert"></p></div>`;document.body.append(gate);}
 $('#end-run').onclick=async()=>{const b=$('#end-run');b.disabled=true;try{await handle('return');}catch(e){gate.querySelector('.return-error').textContent=e.message;b.disabled=false;}};
 if(!$('#modal').open)$('#end-run').focus({preventScroll:true});
}
$('#modal').addEventListener('close',()=>{if(state)renderReturnGate();});
document.addEventListener('keydown',e=>{if(state&&awaitingReturn(state)&&!$('#modal').open&&e.key==='Tab'){e.preventDefault();$('#end-run')?.focus();}});

function reportPanelSwitch(){return demoMode?`<div class="period-switch report-panels" aria-label="Report section"><button data-action="cost-panel" data-id="charts" class="${reportPanel==='charts'?'primary':''}" aria-pressed="${reportPanel==='charts'}">Shift performance</button><button data-action="cost-panel" data-id="costs" class="${reportPanel==='costs'?'primary':''}" aria-pressed="${reportPanel==='costs'}">Cost comparison</button></div>`:`<div class="hint">Curious about DoorDash / Uber Eats costs? <a href="?demo=1&report=costs">Explore the sample cost comparison →</a></div>`;}
function costReportsView(){return header('The value of your own delivery team.','Explore fees avoided, estimated savings, and evidence of better delivery work.')+reportPanelSwitch()+`<section class="card cost-range"><div class="form-grid"><div><label for="from">From date</label><div class="date-input-wrap"><input id="from" type="date" value="${range.from}"></div></div><div><label for="to">Through date</label><div class="date-input-wrap"><input id="to" type="date" value="${range.to}"></div></div></div><div class="actions"><button data-action="filter">Apply date range</button>${['weekly','monthly','yearly'].map(v=>`<button data-period="${v}" class="${reportView===v?'primary':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></section>`+costLab(state,filtered(),costAssumptions,businessAssumptions);}
function bindCostLab(){const form=$('#cost-form');if(!form)return;const apply=()=>{try{const raw=Object.fromEntries(new FormData(form));raw.ddTablet=!!raw.ddTablet;costAssumptions=validateCostInputs(raw);range=reportDateRange($('#from').value,$('#to').value);render();}catch(e){$('#cost-error').textContent=e.message;}};form.onsubmit=e=>{e.preventDefault();apply();};document.querySelectorAll('[data-cost-preset]').forEach(b=>b.onclick=()=>{const shares={solo:[70,25,5],balanced:[45,40,15],family:[15,35,50]}[b.dataset.costPreset];['soloShare','duoShare','familyShare'].forEach((k,i)=>form.elements[k].value=shares[i]);apply();});$('[data-cost-reset]').onclick=()=>{costAssumptions={...COST_DEFAULTS};businessAssumptions={...BUSINESS_DEFAULTS};render();};}

function bindBusinessLab(){if(!demoMode||!$('#business-form'))return;const update=()=>{range=reportDateRange($('#from').value,$('#to').value);render();};document.querySelectorAll('[data-business-role]').forEach(b=>b.onclick=()=>{businessAssumptions={...businessAssumptions,avoidablePercent:Number(b.dataset.businessRole)};update();});for(const [selector,errorId] of [['#business-form','#business-error'],['#entry-form','#entry-error']])$(selector).onsubmit=e=>{e.preventDefault();try{const raw=Object.fromEntries(new FormData(e.target));if(selector==='#entry-form')raw.entryScenario=!!raw.entryScenario;businessAssumptions=validateBusinessInputs({...businessAssumptions,...raw});update();}catch(err){$(errorId).textContent=err.message;}};}

function manageCustomers(){dialog('Saved customers',`<p class="muted">${state.customers.length} records. Delete removes linked contact details; shift totals stay.</p><button type="button" class="danger" id="manage-delete-all" ${state.customers.length?'':'disabled'}>Delete all saved customers</button>${state.customers.map(c=>`<div class="row"><span>${esc(c.name||'Unnamed customer')}</span><button type="button" class="link" data-manage-delete="${c.id}">Delete customer</button></div>`).join('')}`,null,'Save','Done');$('#manage-delete-all').onclick=()=>handle('delete-all-customers');$('#modal').querySelectorAll('[data-manage-delete]').forEach(b=>b.onclick=()=>handle('delete-customer',b.dataset.manageDelete));}
function groupExistingOrders(selected){const shift=active();if(!shift)return;const singles=state.deliveries.filter(d=>d.shiftId===shift.id&&!d.batchId&&['pending','ready'].includes(d.status)),batches=[...new Set(state.deliveries.filter(d=>d.shiftId===shift.id&&d.batchId&&d.status!=='canceled').map(d=>d.batchId))].filter(canAppendBatch);dialog('Group existing orders',`${selected&&batches.length?`<h3>Add this order to a current batch</h3>${batches.map((key,i)=>`<button type="button" class="run-choice" data-existing-target="${key}">Batch ${i+1} · ${state.deliveries.filter(d=>d.batchId===key&&d.status!=='canceled').length} orders</button>`).join('')}<hr>`:''}<p>Choose at least two pending or ready single orders for a new batch. An order already out for delivery cannot be moved here.</p>${singles.map(d=>`<label class="checkbox-label"><input type="checkbox" name="orders" value="${d.id}" ${d.id===selected?'checked':''}> ${esc(d.name||d.address)} · ${esc(d.address)}</label>`).join('')||'<p>No available single orders.</p>'}`,async f=>{const batch=id();await mutate(v=>mergeOrders(v,shift.id,f.getAll('orders'),batch));expandedBatches.add(batch);tab='deliveries';render();},'Create batch');$('#modal').querySelectorAll('[data-existing-target]').forEach(b=>b.onclick=async()=>{try{await mutate(v=>moveOrderToBatch(v,selected,b.dataset.existingTarget));expandedBatches.add(b.dataset.existingTarget);$('#modal').close();render();}catch(e){$('#modal .error').textContent=e.message;}});}
function checkAlcoholReceiptJar(runId){if($('#modal').open||awaitingReturn(state))return;const run=state.runs.find(r=>(!runId||r.id===runId)&&r.needsAlcoholReceiptJar&&!r.alcoholReceiptJarAt&&r.returnedAt);if(!run)return;dialog('Alcohol receipt for Ang',`<p>You’re back at the restaurant. Put the signed alcohol receipt in the jar.</p><label class="checkbox-label"><input name="stored" type="checkbox" required> Signed receipt(s) are in the jar.</label>`,async()=>mutate(v=>{v.runs.find(r=>r.id===run.id).alcoholReceiptJarAt=now();}),'Confirm','Later');}
function exportShiftDetails(shiftId){const shift=state.shifts.find(s=>s.id===shiftId&&s.status==='finalized');if(!shift)throw Error('Choose a completed shift in History.');const rows=detailCSVRows(state,[shift]);download(`delivery-${demoMode?'SAMPLE-':''}shift-${localDate(shift.startedAt)}-${shift.id}-details.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');notify('Delivery details and completed tasks exported for this shift.');}
function cateringPhotosDialog(deliveryId,after){const delivery=()=>state.deliveries.find(d=>d.id===deliveryId);if(!delivery())throw Error('Order not found.');dialog('Catering delivery photos',`<p>After delivery and set-up, take both photos. They are saved only on this device and included in full backups.</p>${['setup','receipt'].map(k=>`<section class="catering-photo"><label for="catering-${k}">${k==='setup'?'Food set-up':'Receipt'} photo</label><input id="catering-${k}" type="file" accept="image/*" capture="environment" data-catering-input="${k}"><div data-catering-preview="${k}"></div></section>`).join('')}<p id="catering-save-status" role="status"></p><button type="button" class="primary" id="share-catering">Share both photos with Mike</button><p class="muted">Choose Messages in the share sheet and select Mike. The browser cannot preselect a recipient while attaching photos.</p><button type="button" id="copy-mike">Copy Mike’s number</button>`,after?async()=>{requireCateringPhotos(delivery());after();}:null,after?'Continue to delivery confirmation':'Save','Done');const draw=()=>{for(const k of ['setup','receipt']){const p=delivery().cateringPhotos?.[k];$(`[data-catering-preview="${k}"]`).innerHTML=p?`<img src="${p.data}" alt="${k==='setup'?'Catering set-up':'Catering receipt'}"><small>Saved on this device</small>`:'<p class="muted">Photo required before delivery completion.</p>';}};draw();let saving=false;const photoForm=$('#modal form');$('#modal').querySelectorAll('[data-catering-input]').forEach(input=>input.onchange=async()=>{if(!input.files[0]||saving)return;saving=true;const button=$('#modal [type=submit]');if(button)button.disabled=true;try{const photo=await storedPhoto(input.files[0]);await mutate(v=>{const d=v.deliveries.find(d=>d.id===deliveryId);d.cateringPhotos??={};d.cateringPhotos[input.dataset.cateringInput]=photo;});if(!photoForm.isConnected)return;draw();$('#catering-save-status').textContent='Photo saved on this device.';}catch(e){if($('#catering-save-status'))$('#catering-save-status').textContent=e.message;}finally{saving=false;if(button)button.disabled=false;input.value='';}});$('#share-catering').onclick=()=>shareCatering(deliveryId);$('#copy-mike').onclick=()=>navigator.clipboard.writeText(state.settings.mike).then(()=>notify('Mike’s number copied.')).catch(()=>notify('Mike: '+state.settings.mike));}
async function shareCatering(deliveryId){try{if(demoMode)throw Error('Photo sharing is disabled in sample mode.');const d=state.deliveries.find(d=>d.id===deliveryId);requireCateringPhotos(d);const files=cateringFiles(d);if(!navigator.canShare?.({files}))throw Error('File sharing is unavailable here. Open this app on iPhone to share the saved photos.');await navigator.share({files,title:'Catering delivery photos',text:'Catering delivery completed. Set-up and receipt photos.'});notify('Share sheet closed. The app cannot confirm a message was sent.');}catch(e){if(e.name!=='AbortError')notify(e.message);}}

function scannerSettings(){const status=cloudScanStatus();return `<section class="card"><h2>In-app ticket scanner</h2><p>${status.enabled?'Connected on this device. New single deliveries and batch stops open the rear camera automatically.':'Tap Scan ticket in an order to connect this device once using the driver setup code. After connection, new single deliveries and batch stops open the camera automatically.'}</p><p class="muted">Cloudflare processes captured ticket photos temporarily, including customer details. No photos or extracted text are stored or logged by our scanner service. The free allowance stops at its limit, with no paid fallback. Saved customer records and downloaded exports remain local. Cloud scanning also uses the allowance in sample mode.</p>${status.enabled?'<button data-action="disable-scanner">Disable cloud scanning</button>':''}</section>`;}
